// src/pages/Login.jsx
import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useTheme } from "../context/ThemeContext";
import { login } from "../api/auth";

const Login = () => {
  const { colors } = useTheme();
  const navigate = useNavigate();

  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");

  const [error, setError] = useState("");
  const [loading, setLoading] = useState(false);

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    if (!email || !password) {
      setError("Please enter your email and password.");
      return;
    }

    try {
      setLoading(true);

      // ✅ Real login via Django JWT: /api/v1/token/
      const data = await login(email, password);

      // Optional: store user info if backend returns it
      if (data?.user?.email) localStorage.setItem("userEmail", data.user.email);
      else localStorage.setItem("userEmail", email);

      navigate("/dashboard");
    } catch (err) {
      // axios error handling (safe)
      const msg =
        err?.response?.data?.detail ||
        err?.response?.data?.message ||
        "Login failed. Check email/password.";
      setError(msg);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div
      style={{
        minHeight: "calc(100vh - 80px)",
        backgroundColor: colors.pageBg,
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        padding: "40px 16px",
      }}
    >
      <div
        style={{
          width: "100%",
          maxWidth: "420px",
          backgroundColor: colors.cardBg,
          borderRadius: "18px",
          padding: "32px 32px 28px",
          boxShadow: "0 18px 45px rgba(15,23,42,0.45)",
          color: colors.text,
        }}
      >
        <h2
          style={{
            textAlign: "center",
            marginBottom: "8px",
            fontSize: "22px",
          }}
        >
          Log in
        </h2>

        <p
          style={{
            textAlign: "center",
            marginBottom: "24px",
            fontSize: "13px",
            opacity: 0.85,
          }}
        >
          Access your thesis checks, reports and dashboard.
        </p>

        <form onSubmit={handleSubmit}>
          <div style={{ marginBottom: "16px" }}>
            <label
              style={{
                display: "block",
                marginBottom: "6px",
                fontSize: "13px",
              }}
            >
              Email
            </label>

            <input
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              style={{
                width: "100%",
                padding: "10px 14px",
                borderRadius: "999px",
                border: "1px solid rgba(148,163,184,0.6)",
                outline: "none",
              }}
            />
          </div>

          <div style={{ marginBottom: "18px" }}>
            <label
              style={{
                display: "block",
                marginBottom: "6px",
                fontSize: "13px",
              }}
            >
              Password
            </label>

            <input
              type="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              style={{
                width: "100%",
                padding: "10px 14px",
                borderRadius: "999px",
                border: "1px solid rgba(148,163,184,0.6)",
                outline: "none",
              }}
            />
          </div>

          {error && (
            <p
              style={{
                color: "#f97373",
                fontSize: "12px",
                marginBottom: "10px",
                textAlign: "center",
              }}
            >
              {error}
            </p>
          )}

          <button
            type="submit"
            disabled={loading}
            style={{
              width: "100%",
              padding: "10px 18px",
              borderRadius: "999px",
              border: "none",
              cursor: loading ? "not-allowed" : "pointer",
              background: "linear-gradient(135deg, #fbbf24, #f97316)",
              color: "#111827",
              fontWeight: 600,
              fontSize: "14px",
              marginBottom: "14px",
              opacity: loading ? 0.8 : 1,
            }}
          >
            {loading ? "Logging in..." : "Log in"}
          </button>
        </form>

        <p
          style={{
            textAlign: "center",
            fontSize: "13px",
            marginTop: "4px",
          }}
        >
          Don&apos;t have an account?{" "}
          <Link to="/signup" style={{ color: "#fbbf24" }}>
            Sign up
          </Link>
        </p>
      </div>
    </div>
  );
};

export default Login;
